/*
 * Sound cues and spoken feedback.
 *
 * The brief asks for audio on the important functions: errors, prompts for
 * input, and a notification when a model has loaded or a prediction has
 * finished.  Those are the six WAV files in static/sounds, generated by
 * make_sounds.py so their licence is not in question.
 *
 * On top of that there is a spoken readout of the results using the browser's
 * own speech synthesis.  That matters more than the beeps do: a chime tells an
 * auditory learner that something finished, but speech tells them what the
 * answer was, without reading the numbers off the screen.  It follows the
 * interface language, so switching to Bahasa Melayu or Arabic changes the voice
 * as well as the text.
 *
 * Everything degrades quietly.  If the browser blocks autoplay, has no voices
 * installed, or has no speech synthesis at all, the interface keeps working and
 * simply says nothing - audio is a second channel here, never the only one.
 */

const CUES = ["ready", "model_loaded", "predict_done", "error", "prompt", "click"];

const audio = {
  enabled: true,
  speaking: false,
  volume: 0.6,
  clips: {},
  unlocked: false,

  /* Every event that counts as "the user has interacted with the page".  All of
   * them are listened for rather than just pointerdown, because which ones a
   * browser actually delivers varies - with a mouse, a touchscreen, a keyboard,
   * and under automation - and if the one we picked never arrives the interface
   * is silent for the whole session with nothing to show why. */
  GESTURES: ["pointerdown", "mousedown", "touchstart", "keydown", "click"],

  load() {
    CUES.forEach((name) => {
      const clip = new Audio(`/static/sounds/${name}.wav`);
      clip.preload = "auto";

      /* Fetch now.  Setting preload is only a hint and Chrome often ignores it
       * until the first play(), which would make the very first cue of the
       * session arrive late or not at all.  Downloading needs no permission -
       * only playing does. */
      clip.load();

      this.clips[name] = clip;
    });

    /* Browsers refuse to play audio until the user has interacted with the page,
     * so the "ready" cue waits for the first interaction.  Playing earlier just
     * produces a console warning and no sound. */
    const unlock = () => {
      if (this.unlocked) return;
      this.unlocked = true;
      this.play("ready");
      this.GESTURES.forEach((name) => document.removeEventListener(name, unlock));
    };
    this.GESTURES.forEach((name) => document.addEventListener(name, unlock));
  },

  play(name) {
    if (!this.enabled) return;

    const clip = this.clips[name];
    if (!clip) return;

    clip.volume = this.volume;
    clip.currentTime = 0;

    /* play() returns a promise that rejects when autoplay is blocked.  That is
     * expected before the first interaction, so it is swallowed rather than
     * logged - a console full of warnings makes real errors harder to spot. */
    const started = clip.play();
    if (started && started.catch) started.catch(() => {});
  },

  /* Named wrappers, so the calling code reads as intent rather than file names. */
  modelLoaded() { this.play("model_loaded"); },
  predictionDone() { this.play("predict_done"); },
  error() { this.play("error"); },
  prompt() { this.play("prompt"); },
  click() { this.play("click"); },

  setEnabled(on) {
    this.enabled = on;
    if (on) this.play("click");
  },

  setVolume(fraction) {
    this.volume = Math.min(Math.max(fraction, 0), 1);
  },

  /* ------------------------------------------------------------- speech */
  canSpeak() {
    return typeof window.speechSynthesis !== "undefined";
  },

  /* Pick a voice matching the interface language, preferring an exact tag
   * ("ms-MY") and settling for the language family ("ms") if that is all the
   * machine has.  Returning null lets the browser choose its default, which is
   * better than refusing to speak. */
  voiceFor(tag) {
    if (!this.canSpeak()) return null;

    const voices = window.speechSynthesis.getVoices();
    const family = tag.split("-")[0].toLowerCase();

    return voices.find((voice) => voice.lang.toLowerCase() === tag.toLowerCase())
        || voices.find((voice) => voice.lang.toLowerCase().startsWith(family))
        || null;
  },

  speak(text, tag) {
    if (!this.speaking || !this.canSpeak() || !text) return;

    window.speechSynthesis.cancel();

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = tag || "en-GB";
    utterance.rate = 0.98;
    utterance.volume = this.volume;

    const voice = this.voiceFor(utterance.lang);
    if (voice) utterance.voice = voice;

    window.speechSynthesis.speak(utterance);
  },

  stopSpeaking() {
    if (this.canSpeak()) window.speechSynthesis.cancel();
  },

  setSpeaking(on) {
    this.speaking = on;
    if (!on) this.stopSpeaking();
  },
};

/* Voices load asynchronously in Chrome and are an empty list on first call, so
 * the list is refreshed when the browser says it is ready. */
if (audio.canSpeak()) {
  window.speechSynthesis.onvoiceschanged = () => {};
}
